style.css:
@-moz-document domain("youtube.com") {
/* General Button Styles */
    ytd-button-renderer, 
    ytd-toggle-button-renderer {
        position: relative;
        border-radius: 20px !important; /* Rounded corners */
        transition: all 0.3s ease; /* Smooth transition */
    }

    /* LED Glow Effect on Hover */
    ytd-button-renderer:hover::before,
    ytd-toggle-button-renderer:hover::before {
        content: "";
        position: absolute;
        top: -3px; 
        left: -3px;
        right: -3px; 
        bottom: -3px; 
        border-radius: 20px; /* Match button's border-radius */
        border: 2px solid #00ffcc; /* LED color */
        box-shadow: 0 0 5px #00ffcc, 
                    0 0 10px #00ffcc, 
                    0 0 15px #00ffcc; /* Glow effect */
        z-index: -1; /* Behind the button */
    }

    /* Subscribe Button Hover Color */
    #subscribe-button:hover {
        color: #00ffcc !important; /* Change text color on hover */
    }
}
